<?php require_once __DIR__.'/../config.php'; $u=require_admin(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); $action=$_POST['action']??''; if($action==='add'){try{$s=$pdo->prepare('INSERT INTO lines(code,name,origin,destination) VALUES(?,?,?,?)');$s->execute([trim($_POST['code']),trim($_POST['name']),trim($_POST['origin']),trim($_POST['destination'])]);flash('Linha criada.');}catch(Exception $e){flash('Código de linha já existente.');}} elseif($action==='toggle'){$s=$pdo->prepare('UPDATE lines SET active=CASE active WHEN 1 THEN 0 ELSE 1 END WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Estado da linha atualizado.');} redirect('lines.php');}
$rows=$pdo->query('SELECT * FROM lines ORDER BY code')->fetchAll(); layout_start('Linhas',$u); ?>
<div class="page-head"><div><h1>Linhas</h1><p class="muted">Cria e gere as linhas disponíveis para as escalas.</p></div></div><div class="two-col"><section class="card"><h2>Nova linha</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Chapa / código<input name="code" required placeholder="500"></label><label>Nome<input name="name" required placeholder="Porto – Matosinhos"></label><label>Origem<input name="origin"></label><label>Destino<input name="destination"></label><button class="btn primary">Adicionar linha</button></form></section><section class="card"><h2>Linhas existentes</h2><div class="table-wrap"><table><thead><tr><th>Chapa</th><th>Linha</th><th>Percurso</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=$r['code']?></strong></td><td><?=e($r['name'])?></td><td><?=e($r['origin'])?> → <?=e($r['destination'])?></td><td><span class="pill <?= $r['active']?'on':'off'?>"><?= $r['active']?'Ativa':'Desativada'?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="linkbtn"><?= $r['active']?'Desativar':'Ativar'?></button></form></td></tr><?php endforeach; ?></tbody></table></div></section></div>
<?php layout_end(); ?>
